   236|/** Parse `bun test` summary output into real counters. */
   237|export function parseBunTestOutput(output: string): {
   238|  pass: number;
   239|  fail: number;
   240|  failingTestNames: string[];
   241|} {
   242|  let pass = 0;
   243|  let fail = 0;
   244|  // Bun prints e.g. " 12 pass" / " 3 fail" (possibly multiple blocks).
   245|  for (const m of output.matchAll(/^\s*(\d+)\s+pass\s*$/gm)) pass += Number(m[1]);
   246|  for (const m of output.matchAll(/^\s*(\d+)\s+fail\s*$/gm)) fail += Number(m[1]);
   247|  const failingTestNames = Array.from(
   248|    new Set(
   249|      Array.from(output.matchAll(/^\s*(?:✗|\(fail\))\s*(.+?)\s*$/gm))
   250|        .map((m) => String(m[1]).trim())
   251|        .filter(Boolean),
   252|    ),
   253|  ).slice(0, 200);
   254|  return { pass, fail, failingTestNames };
   255|}
