// Self-contained Expo Metro config — no vendor bundler plugin.
//
// The managed preview environment periodically rewrites this file back to the
// vendor default (`withRorkMetro` + a `@rork-ai/toolkit-sdk/metro` require at
// module scope). That revert breaks two guarantees at once:
//
//   1. Independence — the build stops working on any machine where the vendor
//      package is not installed, because the require happens at module scope.
//   2. Bundle safety — the vendor config sets no `babelTransformerPath`, so the
//      IVX transformer that strips non-static AI SDK imports is dropped and the
//      bundle can fail on `import(id)` inside @ai-sdk/provider-utils.
//
// `expo/__tests__/vendor-independence.test.ts` and
// `expo/__tests__/metro-ai-sdk-compatibility.test.ts` both assert this file's
// shape, so a silent revert is caught by the test suite rather than at runtime.
const { getDefaultConfig } = require("expo/metro-config");
const path = require("path");

const config = getDefaultConfig(__dirname);

config.transformer = {
  ...config.transformer,
  babelTransformerPath: path.resolve(__dirname, "scripts/ivx-metro-transformer.js"),
};

module.exports = config;

